using System.Collections;
using Founders.UI;
using UnityEngine;

namespace Founders
{
    /// <summary>
    /// Entry point. The scene (generated by the build script) holds this object, the URP
    /// camera, the sun and the post-processing volume; the world, UI and game state are
    /// created from code, so the game can be developed without opening the Unity editor.
    /// </summary>
    public class GameBootstrap : MonoBehaviour
    {
        void Awake()
        {
            Prefs.Apply();
            Screen.sleepTimeout = SleepTimeout.NeverSleep;
            // Portrait and both landscapes, following the device (the UI and the camera adapt; see GameUi.Portrait).
            // Upside-down portrait only on iPads: iPhones without a home button never use it, and on the others
            // it would put the home indicator and the notch the wrong way round (the player settings allow it so
            // the iPad's Info.plist lists it; this narrows it for iPhones at run time).
            Screen.autorotateToPortrait = true;
            Screen.autorotateToPortraitUpsideDown = IsTablet;
            Screen.autorotateToLandscapeLeft = true;
            Screen.autorotateToLandscapeRight = true;
            Screen.orientation = ScreenOrientation.AutoRotation;
            var ui = GameUi.Create(gameObject);
            ui.Loading.Show();
            ui.Loading.Set(0.08f, "Kindling the hearth…");
            StartCoroutine(Boot(ui));
        }

        /// <summary>True on an iPad (or an Android tablet: the shortest side is at least 600 dp).</summary>
        static bool IsTablet
        {
            get
            {
                if (Application.platform == RuntimePlatform.IPhonePlayer) return SystemInfo.deviceModel.StartsWith("iPad", System.StringComparison.Ordinal);
                float dpi = Screen.dpi > 0 ? Screen.dpi : 160f;
                return Mathf.Min(Screen.width, Screen.height) / dpi * 160f >= 600f;
            }
        }

        IEnumerator Boot(GameUi ui)
        {
            // Two frames so the loading screen is on screen before the heavy work starts.
            yield return null;
            yield return null;

            SceneEnvironment.Apply();
            if (FindAnyObjectByType<Light>() == null) SceneEnvironment.CreateSun();
            // Ambient light from the HDRI sky (the scene is generated headless, so nothing is baked).
            DynamicGI.UpdateEnvironment();
            ui.Loading.Set(0.22f, "Shaping the valley…");
            yield return null;

            bool capture = CaptureDirector.Requested;
            var rig = new GameObject("CameraRig").AddComponent<CameraRig>();
            var world = new GameObject("World").AddComponent<WorldView>();
            var store = gameObject.AddComponent<GameStore>();
            rig.IsBlocked = ui.BlocksPointer;
            rig.OnTap = store.HandleTap;
            rig.GrabAt = store.GrabsGhost;
            rig.OnGrab = store.DragGhost;
            rig.PaintMode = () => store.DecoratingId != null && store.PaintMode;
            rig.OnPaint = store.HandlePaint;
            rig.OnPaintEnd = store.EndPaintStroke;
            store.Init(rig, world, capture);
            gameObject.AddComponent<Atmosphere>().Init(store);
            gameObject.AddComponent<AudioDirector>().Init(store);
            // Pictures of the real buildings for the build menu and the cards (rendered once, then read from disk).
            yield return Thumbnails.Prepare(store.Game.Content, p => ui.Loading.Set(Mathf.Lerp(0.6f, 0.78f, p), "Carving the signs…"));
            ui.Loading.Set(0.78f, "Gathering the people…");
            yield return null;

            ui.Init(store);
            // Let the first frames of the world render (shaders, terrain) under the loading screen.
            for (float t = 0; t < 0.6f; t += Time.unscaledDeltaTime)
            {
                ui.Loading.Set(Mathf.Lerp(0.78f, 1f, t / 0.6f), "Raising the camp…");
                yield return null;
            }
            ui.Loading.Set(1f, "Welcome, Founder");
            yield return new WaitForSecondsRealtime(0.2f);
            ui.Loading.Hide();

            if (capture) gameObject.AddComponent<CaptureDirector>().Begin(store, ui);
        }
    }
}
